package com.smartcanteen.controller;
import org.springframework.http.ResponseEntity;import org.springframework.web.bind.annotation.*;import org.springframework.web.bind.MethodArgumentNotValidException;import java.util.Map;
@RestControllerAdvice public class ApiExceptionHandler {@ExceptionHandler(IllegalArgumentException.class) public ResponseEntity<?> bad(IllegalArgumentException e){return ResponseEntity.badRequest().body(Map.of("message",e.getMessage()==null?"Invalid request.":e.getMessage()));}@ExceptionHandler(MethodArgumentNotValidException.class) public ResponseEntity<?> invalid(MethodArgumentNotValidException e){return ResponseEntity.badRequest().body(Map.of("message","Please check the submitted fields."));}@ExceptionHandler(Exception.class) public ResponseEntity<?> error(Exception e){return ResponseEntity.internalServerError().body(Map.of("message","Unexpected server error. Check backend logs."));}}
